@page "/shipments"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Shipments</PageTitle>

<h1>Shipments</h1>

<div class="mb-3 d-flex justify-content-between align-items-center">
    <div>
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" style="width: 300px;" />
    </div>
    <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4 p-3">
        <h4>Create New Shipment</h4>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
            </div>
            <div class="col-md-3">
                <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
            </div>
            <div class="col-md-9">
                <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
            </div>
            <div class="col-md-3">
                <button class="btn btn-primary w-100" @onclick="CreateShipment" disabled="@creating">Create</button>
            </div>
        </div>
        @if (!string.IsNullOrEmpty(createError))
        {
            <div class="alert alert-danger mt-2">@createError</div>
        }
    </div>
}

@if (loading)
{
    <p>Loading shipments...</p>
}
else if (shipments is null || shipments.Count == 0)
{
    <p class="text-muted">No shipments found.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Recipient</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><a href="track/@shipment.TrackingNumber">@shipment.TrackingNumber</a></td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.RecipientName</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@((int)shipment.Status)"
                                @onchange="e => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    using ShipmentTracker.Client.Models;
    using ShipmentTracker.Client.Services;

    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private bool creating;
    private string? createError;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments ?? []
            : (shipments ?? []).Where(s =>
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task CreateShipment()
    {
        createError = null;
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination) || string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            createError = "Origin, Destination, and Recipient Name are required.";
            return;
        }

        creating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            creating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        _ => "bg-secondary"
    };
}

@page "/track/{TrackingNumber}"

<PageTitle>Track Shipment</PageTitle>

<h1>Track Shipment</h1>

<div class="mb-3">
    <div class="input-group" style="max-width: 400px;">
        <input type="text" class="form-control" placeholder="Enter tracking number" @bind="searchInput" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-outline-primary" @onclick="Search">Search</button>
    </div>
</div>

@if (loading)
{
    <p>Loading...</p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h4 class="mb-0">@shipment.TrackingNumber</h4>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("yyyy-MM-dd")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>@(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "N/A")</dd>
                        <dt>Actual Delivery</dt>
                        <dd>@(shipment.ActualDelivery?.ToString("yyyy-MM-dd") ?? "Pending")</dd>
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrWhiteSpace(shipment.Description))
            {
                <p><strong>Description:</strong> @shipment.Description</p>
            }
        </div>
    </div>

    <div class="mt-4">
        <h5>Shipment Progress</h5>
        <div class="progress" style="height: 30px;">
            <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                 role="progressbar"
                 style="width: @GetProgressPercent(shipment.Status)%"
                 aria-valuenow="@GetProgressPercent(shipment.Status)"
                 aria-valuemin="0"
                 aria-valuemax="100">
                @shipment.Status
            </div>
        </div>
    </div>
}

@code {
    using ShipmentTracker.Client.Models;
    using ShipmentTracker.Client.Services;

    [Parameter] public string TrackingNumber { get; set; } = string.Empty;
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private ShipmentDto? shipment;
    private bool loading = true;
    private string searchInput = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        searchInput = TrackingNumber;
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private void Search()
    {
        if (!string.IsNullOrWhiteSpace(searchInput))
            Navigation.NavigateTo($"track/{searchInput.Trim()}");
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            Search();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-warning",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Returned => 100,
        _ => 0
    };
}

