toolArgs.new_str:
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are logged in as <strong>@context.User.Identity?.Name</strong>.</p>
        <p><a href="shipments" class="btn btn-primary">View All Shipments</a></p>
    </Authorized>
    <NotAuthorized>
        <p>Track your shipment using the tracking number, or <a href="Account/Login">log in</a> to manage shipments.</p>
    </NotAuthorized>
</AuthorizeView>

<div class="mt-4">
    <h3>Track a Shipment</h3>
    <div class="input-group" style="max-width: 400px;">
        <input type="text" class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-outline-secondary" @onclick="TrackShipment">Track</button>
    </div>
    @if (navigating)
    {
        <p class="mt-2 text-muted">Searching...</p>
    }
</div>

@code {
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private bool navigating;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            navigating = true;
            Navigation.NavigateTo($"track/{trackingNumber.Trim()}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

